// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2017, "10-11", [{"author":"Б. Иомдин","question":"Как не говорят?","choices":["<em>то-сё</em>","<em>те-се</em>","<em>туда-сюда</em>","<em>там-сям</em>","<em>так-сяк.</em>"],"key":"Б","review":["Парные разговорные слова","В устойчивых парах повторяется значение с двумя указательными формами: «там» и «сям» обозначают разные места.","Встречаются «то-сё», «туда-сюда», «там-сям» и «так-сяк». Парного выражения «те-се» в русском языке нет."]},{"author":"П. Аркадьев","question":"Какой из этих глаголов относится к несовершенному виду?","choices":["<em>зачитать</em>","<em>отчитать</em>","<em>перечитать</em>","<em>причитать</em>","<em>прочитать</em>."],"key":"Г","review":["Несовершенный вид глагола","Спроси о каждом действии «что делать?» или «что сделать?». Не всякое начало на «при-» указывает на завершённость.","«Причитать» значит протяжно жаловаться или плакать и отвечает на «что делать?». «Зачитать», «отчитать», «перечитать» и «прочитать» отвечают на «что сделать?»."]},{"author":"Б. Иомдин","question":"Какое слово не однокоренное с остальными?","choices":["<em>проголосовать</em>","<em>голосистый</em>","<em>голословный</em>","<em>вполголоса</em>","<em>разноголосица</em>."],"key":"В","review":["Границы корня","Проверь, является ли «голос» частью каждого слова или одинаковые буквы пересекают границу двух корней.","«Голословный» буквально опирается на «голые слова». Его корни связаны с «голый» и «слово». В остальных словах общий корень «голос-»."]},{"author":"Б. Иомдин","question":"В каком примере <em>а то</em> нельзя заменить на <em>ведь</em>?","choices":["<em>Дмитрий Владимирыч, вы ему подскажите, а то он не знает ещё!</em> (В. Шукшин)","<em>Паш, Мишку там успокой. А то он не знает ничего.</em> (Д. Сабитова)","<em>Вы ей объясните, а то она не знает.</em> (Ю. Олеша)","<em>Ты хоть мне правду скажи, а то я не знаю, что ему отвечать.</em> (Э. Володарский)","<em>― Как ты очутился в деревне Красное?\n― А то ты не знаешь.</em> (В. Войнович)"],"key":"Д","review":["Два значения «а то»","В первых репликах одна часть поясняет, зачем что-то сделать. В последней фразе ответ на вопрос дан с иронией.","У Войновича «А то ты не знаешь» означает «ты и так прекрасно знаешь». Замена на «ведь» сделала бы фразу буквальным объяснением и исказила бы её смысл."]},{"author":"М. Рубинштейн","question":"<em>Более глубокое освоение карнавальной традиции Достоевский нашел у Бальзака, Жорж Санд и Виктора Гюго</em> (М. М. Бахтин)<em>.</em> Одно из имён здесь ― на самом деле мужской псевдоним, под которым публиковала свои произведения женщина-писательница. Какое?","choices":["Достоевский","Бальзак","Жорж Санд","Виктор Гюго","М. М. Бахтин."],"key":"В","review":["Имя на обложке","Вспомни автора романа «Консуэло». На её книгах стояло мужское французское имя.","Жорж Санд — псевдоним писательницы Авроры Дюпен. Достоевский, Бальзак, Гюго и Бахтин — имена авторов-мужчин."]},{"author":"Б. Иомдин","question":"В какой цитате есть ошибка?","choices":["<em>Хорошие люди всё время надеются любые проблемы решить к вящей пользе человечества</em> (из журнала).","<em>Некоторые детали Милашевский вырисовывает, но делает это не на вящего</em> (из контрольной работы).","<em>Однажды в траве я наткнулся на льва, к вящему удивлению нас обоих</em> (из газеты).","<em>Ну ещё Шварценеггера не хватает для вящего эффекта</em> (из блога).","<em>К своему вящему стыду, я прочитала все три книги</em> (из социальной сети)."],"key":"Б","review":["Сочетания со словом «вящий»","«Вящий» значит «больший» или «сильнейший». Проверь, какое существительное характеризуется этим словом в каждой цитате.","Нормальны «к вящей пользе», «к вящему удивлению», «для вящего эффекта» и «к вящему стыду». В обороте «делает это не на вящего» пропало существительное и получилась ошибка."]},{"author":"Б. Иомдин","question":"В Словаре Академии Российской 1789 г. встречается помета «обвет.». А какая помета соответствует ей в современных словарях?","choices":["устар.","обл.","офиц.","высок.","груб."],"key":"А","review":["Помета старого словаря","Прочитай сокращение «обвет.» как начало слова о том, что с течением времени утратило силу или вышло из употребления.","«Обвет.» — «обветшалое». В нынешнем словаре подобное слово или значение отмечают «устар.»."]},{"author":"Б. Иомдин","question":"Какое слово не связано по смыслу с возрастом человека?","choices":["<em>старик</em>","<em>старец</em>","<em>старикан</em>","<em>старейшина</em>","<em>старьёвщик</em>."],"key":"Д","review":["Человек и его возраст","Проверь, описывает ли слово возраст человека или то, с чем он работает.","Старьёвщик занимается старьём, например скупает старые вещи. Человек любой возрастной группы может выполнять эту работу."]},{"author":"С. Сай","question":"«В рамках <u>восьмого</u> Фестиваля современного польского кино будет показано <u>пятнадцать</u> новых фильмов молодых польских режиссёров». Как ещё могли бы быть записаны подчёркнутые числительные?","choices":["В первом случае «8-го» или «VIII», во втором — «15» или «XV».","В первом случае «8» или «VIII», во втором — «15» или «XV».","В первом случае «8-го» или «VIII», во втором — «15».","В первом случае «8-го» или «VIII», во втором — «15-ть».","В первом случае «8» или «VIII», во втором — «15»."],"key":"В","review":["Запись числительных","«Восьмого» показывает порядок фестивалей, а «пятнадцать» — количество фильмов. Для двух видов числительных правила различаются.","Порядковое можно записать «8-го» с буквенным окончанием или «VIII». Количественное «пятнадцать» записывают арабскими цифрами «15» без наращения."]},{"author":"Б. Иомдин","question":"Что нас радует, когда ломится?","choices":["компьютер","лифт","машина","стол","стул."],"key":"Г","review":["Выражение о достатке","Вспомни, что может «ломиться от угощений». Здесь глагол передаёт изобилие.","О богатом угощении говорят «стол ломится от еды». Такое описание стола принято в русском языке."]},{"author":"А. Пиперски","question":"Выпишем все русские числительные от 1 до 100: <em>один</em>, <em>два</em>, <em>три</em>, <em>четыре</em>, …, <em>девяносто девять</em>, <em>сто</em> — и посмотрим, какие буквы встречаются в наибольшем количестве элементов этого списка. Буква <em>т</em> встретится в 91 числительном из 100, <em>д</em> — в 86, _ — в 85, <em>е</em> — в 77, <em>с</em> — в 74. Какая буква должна стоять на месте прочерка?","choices":["<em>а</em>","<em>в</em>","<em>о</em>","<em>ь</em>","<em>я</em>."],"key":"Г","review":["Частая буква в числах","Считай, входят ли буквы хотя бы раз в запись числа. Для «ь» удобно сначала отметить десятки, где мягкий знак есть у всех десяти чисел.","По 10 чисел с «ь» дают десятки 20, 30, 50, 60, 70 и 80. Ещё по 5 дают группы 40 и 90, а 15 чисел с «ь» появляются от 1 до 19. Всего 85."]},{"author":"П. Аркадьев","question":"По-русски <em>Георгий</em>, а по-испански?","choices":["<em>Хосе</em>","<em>Хорхе</em>","<em>Хесус</em>","<em>Хиль</em>","<em>Хуан</em>."],"key":"Б","review":["Имя на испанском","Сопоставь Георгия с известными носителями того же имени в других языках: Джорджем или Жоржем.","По-испански Георгий — Хорхе. Хосе соответствует Иосифу, Хесус — Иисусу, Хуан — Ивану."]},{"author":"Е. Бикмаев","question":"Дана цитата: «Сыны любимые победы сквозь огнь окопов рвутся шведы» (А. С. Пушкин). Где нужно поставить запятые по современным правилам пунктуации?","choices":["только после слова <em>сыны</em>","после слова <em>любимые</em>","только после слова <em>победы</em>","после слова <em>сыны</em> и после слова <em>победы</em>","знаки препинания не нужны."],"key":"В","review":["Запятая в строке Пушкина","Верни прямой порядок слов: «шведы, сыны любимые победы, рвутся сквозь огнь окопов».","При исходном порядке обособленное приложение «сыны любимые победы» стоит в начале. Запятая закрывает его после «победы»."]},{"author":"И. Рубанов","question":"Ваня предложил Маше руку и сердце, но получил ... .","choices":["отворот-поворот","отврат-поворот","отворот и поворот","от ворот отворот","от ворот поворот."],"key":"Д","review":["Ответ на предложение","Герой получил отказ. Вспомни устойчивый образ, при котором с порога поворачивают назад.","Отказ в сватовстве и вообще резкий отказ называют «от ворот поворот». Этот оборот и дополняет предложение."]},{"author":"И. Иткин","question":"Русское слово <em>трезвонить</em> обладает одной редкой особенностью. Какое из следующих слов обладает той же особенностью?","choices":["<em>трепыхаться</em>","<em>треугольный</em>","<em>треволнение</em>","<em>треножник</em>","<em>трещотка</em>."],"key":"В","review":["Редкое начало слова","Отдели начало «тре-» и спроси, указывает ли оно на ровно три предмета или усиливает значение оставшейся части.","«Треволнение» означает сильное волнение, как «трезвонить» означает сильно, многократно звонить. В «треугольный» и «треножник» часть «тре-» обозначает количество."]},{"author":"Е. Бикмаев","question":"Какое устойчивое выражение устроено по смыслу не так, как остальные?","choices":["<em>второе дыхание</em>","<em>третий глаз</em>","<em>шестое чувство</em>","<em>седьмое небо</em>","<em>восьмое чудо света</em>."],"key":"Г","review":["Числа в устойчивых оборотах","Сравни число в каждом выражении с тем количеством, которое принято считать обычным: два глаза, пять чувств, семь чудес.","«Второе дыхание», «третий глаз», «шестое чувство» и «восьмое чудо» добавляют ещё один элемент. «Седьмое небо» — самое высокое из семи, уже входящее в традиционный ряд."]},{"author":"Б. Иомдин","question":"Все эти слова восходят к греческому языку, но одно из них несколько видоизменилось, пройдя на пути к русскому через другой язык. Какое?","choices":["<em>анализ</em>","<em>синтез</em>","<em>синтетика</em>","<em>паралич</em>","<em>паралитик.</em>"],"key":"Г","review":["Путь заимствования","Поставь рядом «паралич» и «паралитик». У этих слов общий древний источник, но согласные в корне различаются.","Форма «паралич» пришла в русский через польское «paraliż». Этим путём объясняется её отличие от форм греческого корня в «паралитик» и «парализовать»."]},{"author":"А. Пиперски","question":"Какое из этих слов обычно склоняется несколько иначе, чем остальные?","choices":["<em>американец</em>","<em>иранец</em>","<em>корсиканец</em>","<em>пакистанец</em>","<em>тайванец</em>."],"key":"Д","review":["Названия жителей","Поставь все слова в родительный падеж и сравни, сохраняется ли твёрдый согласный перед «ц».","Получаются «американца», «иранца», «корсиканца», «пакистанца», но «тайваньца». Мягкость связана с названием «Тайвань»."]},{"author":"С. Сай","question":"В текстах Национального корпуса русского языка союз <em>и</em> используется чаще союзов <em>а</em> и <em>но</em>. Однако перед некоторыми выражениями союзы <em>а</em> и <em>но</em> встречаются чаще, чем <em>и</em>. К каким из выражений <em>в действительности</em>, <em>в самом деле</em>, <em>действительно</em>, <em>на самом деле</em> это относится?","choices":["<em>в действительности</em>, <em>на самом деле</em>","<em>действительно</em>, <em>на самом деле</em>","<em>в действительности</em>, <em>в самом деле</em>","<em>действительно</em>, <em>в самом деле</em>","<em>действительно</em>, <em>в самом деле</em>, <em>на самом деле</em>."],"key":"А","review":["Союз перед выражением","Подумай, какие выражения часто вводят поправку к уже сказанному о том, как на самом деле обстоят дела.","«А в действительности» и «но на самом деле» вводят противопоставление. По данным из условия именно у «в действительности» и «на самом деле» союзы «а», «но» опережают «и»."]},{"author":"С. Сай","question":"В ходе Великой французской революции традиционные системы мер упорядочили и преобразовали так, чтобы сделать их более стройными и логичными. Среди прочего год был по-новому поделён на 12 месяцев, для которых были созданы новые названия. Если сопоставить французский республиканский календарь с привычным нам григорианским, то получится, что вандемьер начинался 22 сентября, жерминаль — 21 марта, нивоз — 21 декабря, термидор — 19 июля, флореаль — 20 апреля, фример — 21 ноября, фрюктидор — 18 августа. А какой месяц французского республиканского календаря начинался 19 июня?","choices":["брюмер","вантоз","мессидор","плювиоз","прериаль."],"key":"В","review":["Смена месяца в календаре","Найди соседний месяц с известной датой начала. В республиканском календаре каждый месяц длился ровно 30 дней.","Термидор начинался 19 июля. За 30 дней до этого начинался предыдущий летний месяц на «-дор». Из вариантов это мессидор."]},{"author":"И. Рубанов","question":"Андрей закончил школу с золотой медалью. Борис завоевал бронзовую медаль на соревнованиях по бегу. Василий награждён медалью «За спасение погибавших». Григорий изготавливает медали в мастерской. Денис купил в магазине шоколадную медаль. Сколько среди них медалистов?","choices":["один","два","три","четыре","пять."],"key":"Б","review":["Кого назовут медалистом","Сравни школьный и спортивный результаты с наградой за поступок, ремеслом и покупкой.","В обычной речи медалистами называют Андрея и Бориса, получивших медали за учёбу и спортивный результат. Василий награждён медалью за поступок."]},{"author":"П. Аркадьев","question":"Какой из знаменитых циклов песен для голоса и фортепиано был сочинён композитором незадолго до кончины, а опубликован и получил своё название лишь после смерти автора?","choices":["«Без солнца» Модеста Мусоргского","«К далёкой возлюбленной» Людвига ван Бетховена","«Любовь поэта» Роберта Шумана","«Прекрасная Магелона» Иоганнеса Брамса","«Лебединая песня» Франца Шуберта."],"key":"Д","review":["Песенный цикл и название","Ищи заглавие, которое обозначает последнее произведение автора. Так мог назвать цикл человек, публиковавший его посмертно.","Песни Шуберта были изданы после его смерти как «Лебединая песня». Название дал издатель, объединивший эти поздние вещи."]},{"author":"А. Кухто","question":"Дана цитата с пропуском из дневника А. Н. Вульфа, друга А. С. Пушкина: <em>Вот наступил … год царствования Николая; прошла первая олимпиада, но мало кажется сделалось улучшений в продолжение этого времени.</em> Слово <em>олимпиада</em> в этой цитате употреблено необычным образом. Опираясь на его значение, восстановите пропущенное слово.","choices":["второй","четвёртый","пятый","седьмой","десятый."],"key":"В","review":["Промежуток в дневнике","Вспомни, сколько лет проходит от одних Олимпийских игр до следующих. Речь идёт об истёкшем промежутке времени.","Олимпиада в этом старом значении — четырёхлетие. После первого четырёхлетия царствования начался пятый год."]},{"author":"Б. Иомдин","question":"Какое слово не заимствовано?","choices":["<em>лифт</em>","<em>этаж</em>","<em>перила</em>","<em>квартира</em>","<em>пандус</em>."],"key":"В","review":["Исконное слово","Одно из слов было в русском языке ещё до заимствования современных названий зданий и их частей.","«Перила» — исконное слово. «Лифт» пришло из английского, «этаж» и «пандус» имеют французское происхождение, «квартира» пришла через польский."]},{"author":"Е. Муравенко","question":"В каком предложении выделенное слово выполняет не ту синтаксическую функцию, что в остальных предложениях?","choices":["<em>Мы отдыхали на море <strong>неделю</strong></em>.","<em>Она провела в деревне <strong>неделю</strong></em>.","<em>Он отсутствовал в школе <strong>неделю</strong></em>.","<em>Они не виделись <strong>неделю</strong></em>.","<em>Ты не звонил мне <strong>неделю</strong></em>."],"key":"Б","review":["Синтаксическая роль «неделю»","Задай вопрос от глагола. Сравни «сколько времени длилось действие?» и «что она провела?».","В ответе «Она провела в деревне неделю» слово «неделю» — прямое дополнение. В других предложениях оно обозначает длительность и служит обстоятельством."]},{"author":"И. Иткин","question":"Сколько в фамилии <em>Пушкин</em> звуков, которых нет в фамилии <em>Шукшин</em>?","choices":["ни одного","один","два","три","четыре."],"key":"Г","review":["Звуки в двух фамилиях","Произнеси обе фамилии и сравни мягкость «к», а также гласные после «к» и «ш».","В «Пушкин» есть [п], [к’] и [и]. В «Шукшин» отсутствует [п], согласный [к] твёрдый, а после [ш] произносится [ы]. Получается три звука."]},{"author":"С. Переверзева","question":"<em>Дал поэт на обед _____ соловью,\nА факир отогрел на груди змею,\nИ Макар никуда не гонял телят,\nЛьётся с гуся вода — всё идёт не в лад!</em> (В. Татаринов. «Не везёт»)\nКак правильно заполнить пропуск?","choices":["<em>песню</em>","<em>басню</em>","<em>рифму</em>","<em>прозу</em>","<em>зёрна</em>."],"key":"Б","review":["Перепутанные поговорки","В тексте устойчивые выражения нарочно осуществляются наоборот. Вспомни, чем согласно поговорке нельзя накормить соловья.","Соловья баснями не кормят. В песне Татаринова поэт поступает наоборот и даёт соловью басню."]},{"author":"О. Душкина","question":"Перед вами отрывок из стихотворения С. А. Есенина «Голубень»:\n<em>С пустых лощин ползёт дугою тощей\nСырой туман, курчаво свившись в мох,\nИ вечер, свесившись над речкою, полощет\nВодою белой пальцы синих ног.</em>\nВ какой из строк этого отрывка есть отступление от нормативного произношения русского языка?","choices":["в первой","во второй","в третьей","в четвёртой","отступлений нет."],"key":"Г","review":["Произношение в рифме","Сравни концы второй и четвёртой строк. В слове «ног» последний согласный обычно произносится как [к].","Слово «ног» здесь рифмуется с «мох». Рифма требует ненормативного для современного языка произношения «ног» с конечным [х]."]},{"author":"Б. Иомдин","question":"В древнерусском языке было слово <em>ясало</em>. В современном русском языке есть слово с тем же значением, которое исторически содержало приставку и тот же корень. А как выглядит суффикс этого современного слова?","choices":["<em>-ал-</em>","<em>-ник-</em>","<em>-альц-</em>","<em>-к-</em>","это слово не имеет суффикса."],"key":"Д","review":["Устройство старого слова","«Ясало» называло то, чем опоясывали одежду. Сопоставь его с нынешним названием этого предмета.","«Ясало» — «пояс». Исторически в слове «пояс» есть приставка «по-» и тот же корень «-яс-», а суффикса нет."]},{"author":"Б. Иомдин","question":"В некоторых книгах по русскому языку и лингвистике как пример редкого явления приводится фраза И. Сельвинского: <em>_________ у аэроплана</em>. Мы пропустили в этой фразе фамилию известного лётчика … .","choices":["Луи Блерио","Константина Кантакузино","Эриха Хартманна","Павла Тарана","Валерия Чкалова."],"key":"А","review":["Гласные подряд","Смотри, какой фамилией можно продолжить цепочку гласных звуков перед словами «у аэроплана».","Сельвинский написал «Сам Блерио у аэроплана». На стыке «Блерио у аэроплана» получается длинная цепочка гласных без согласной между ними."]}], {"year":2017,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2017-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
